private static int decodeOctets(int i,ByteBuffer bb,StringBuilder sb){
    while (bb.hasRemaining()) {
        int b1 = bb.get() & 0xFF;
        if ((b1 & 0x80) == 0) { // ASCII
            sb.append((char) b1);
            i++;
        } else if ((b1 & 0xE0) == 0xC0) { // 2-byte character
            if (bb.hasRemaining()) {
                int b2 = bb.get() & 0xFF;
                sb.append((char) ((b1 & 0x1F) << 6 | (b2 & 0x3F)));
                i += 2;
            } else {
                break;
            }
        } else if ((b1 & 0xF0) == 0xE0) { // 3-byte character
            if (bb.remaining() >= 2) {
                int b2 = bb.get() & 0xFF;
                int b3 = bb.get() & 0xFF;
                sb.append((char) ((b1 & 0x0F) << 12 | (b2 & 0x3F) << 6 | (b3 & 0x3F)));
                i += 3;
            } else {
                break;
            }
        } else if ((b1 & 0xF8) == 0xF0) { // 4-byte character
            if (bb.remaining() >= 3) {
                int b2 = bb.get() & 0xFF;
                int b3 = bb.get() & 0xFF;
                int b4 = bb.get() & 0xFF;
                int codePoint = ((b1 & 0x07) << 18 | (b2 & 0x3F) << 12 | (b3 & 0x3F) << 6 | (b4 & 0x3F));
                sb.append(Character.toChars(codePoint));
                i += 4;
            } else {
                break;
            }
        } else {
            // Invalid UTF-8 sequence
            break;
        }
    }
    return i;
}

