private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    for (int num : bounds) {
        totalSum += num;
    }
    long currentSuffixSum = totalSum;
    for (int num : bounds) {
        suffixSum.add((int) currentSuffixSum);
        currentSuffixSum -= num;
    }
    return new Pair<>(suffixSum, totalSum);
}

