private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    for (V loc0 : vertices) {
        for (V loc1 : vertices) {
            if (loc0 != loc1 && graph.getEdge(loc0, loc1) == null) {
                return false;
            }
        }
    }
    return true;
}

